/* pick1 (decision 0242): API-call recorder for the NATIVE build (link-time wrappers, -Wl,--wrap=fle_imp_NAME for every runtime import; the wrappers are generated by gen-apiwrap.py).
 * It does not change what the guest or the runtime does: it counts the calls, and for a few APIs (the capability probes and the window / layered-window calls) it keeps the arguments, the string arguments and the return value.
 * Output file $APIW_OUT, written at every `cpu LABEL` line of a G3 native script (the harness calls getrusage there; this file wraps getrusage) and at exit.
 *   "#dump N clock_ms MS"        one block per dump; the counts are the calls since the previous dump
 *   "A NAME COUNT"               calls of runtime import NAME since the previous dump
 *   "P NAME COUNT ARGS ret=V"    probe row (distinct arguments and return value), calls since the previous dump
 *   "E MS NAME ARGS ret=V"       one row per call of an event API (window creation / destruction / layered / z-order), in order
 * THE INPUT IS A HARNESS SIMULATION (G3 script). Nothing here is a stand-in for the engine. */
#define _GNU_SOURCE
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/uio.h>
#include <sys/resource.h>
#include "fle_runtime.h"
#include "apiw.h"

extern uint64_t fle_sys_clock_ticks(void);
extern apiw_t apiw_tab[];
extern unsigned apiw_n;
int __real_getrusage(int who, struct rusage *ru);

static int peek(uint64_t addr, void *buf, size_t n)
{
    struct iovec l, r;
    if (addr < 0x1000) return 0;
    l.iov_base = buf; l.iov_len = n; r.iov_base = (void *)(uintptr_t)addr; r.iov_len = n;
    return process_vm_readv(getpid(), &l, 1, &r, 1, 0) == (ssize_t)n;
}

static void rd_w(uint64_t a, char *out, size_t cap)
{
    size_t i = 0;
    if (a < 0x10000) { snprintf(out, cap, "#atom%llu", (unsigned long long)a); return; }
    for (; i + 1 < cap; i++) {
        uint16_t c;
        if (!peek(a + 2 * i, &c, 2)) { if (!i) snprintf(out, cap, "(unreadable)"), i = strlen(out); break; }
        if (!c) break;
        out[i] = c < 0x20 || c > 0x7e ? '?' : (char)c;
    }
    out[i] = 0;
}
static void rd_a(uint64_t a, char *out, size_t cap)
{
    size_t i = 0;
    if (a < 0x10000) { snprintf(out, cap, "#ord%llu", (unsigned long long)a); return; }
    for (; i + 1 < cap; i++) {
        uint8_t c;
        if (!peek(a + i, &c, 1)) { if (!i) snprintf(out, cap, "(unreadable)"), i = strlen(out); break; }
        if (!c) break;
        out[i] = c < 0x20 || c > 0x7e ? '?' : (char)c;
    }
    out[i] = 0;
}
static void rd_g(uint64_t a, char *out, size_t cap)
{
    uint8_t g[16];
    if (!peek(a, g, 16)) { snprintf(out, cap, "(unreadable)"); return; }
    snprintf(out, cap, "{%02X%02X%02X%02X-%02X%02X-%02X%02X-%02X%02X-%02X%02X%02X%02X%02X%02X}", g[3], g[2], g[1], g[0], g[5], g[4], g[7], g[6], g[8], g[9], g[10], g[11], g[12], g[13], g[14], g[15]);
}

typedef struct { uint64_t h, bits; int w, hh, bpp, topdown; } dib_t;
#define NDIB 8192
static dib_t dibs[NDIB]; static unsigned ndib;
typedef struct { uint64_t dc, bmp; } sel_t;
#define NSEL 1024
static sel_t sels[NSEL];
static dib_t *dib_find(uint64_t h) { for (unsigned i = 0; i < ndib; i++) if (dibs[i].h == h) return &dibs[i]; return 0; }
static void dib_add(uint64_t h, uint64_t bits, int w, int hh, int bpp)
{
    dib_t *d = dib_find(h);
    if (!d) { if (ndib == NDIB) { memmove(dibs, dibs + NDIB / 2, sizeof(dib_t) * (NDIB / 2)); ndib = NDIB / 2; } d = &dibs[ndib++]; }
    d->h = h; d->bits = bits; d->w = w; d->hh = hh < 0 ? -hh : hh; d->topdown = hh < 0; d->bpp = bpp;
}
static void sel_set(uint64_t dc, uint64_t bmp) { sel_t *s = &sels[(dc >> 2) % NSEL]; s->dc = dc; s->bmp = bmp; }
/* sample 8x8 pixels of the source rectangle of a BitBlt and report the alpha byte (bits 24..31) of the 32-bit source DIB */
static void src_alpha(uint64_t srcdc, int sx, int sy, int w, int h, char *buf, size_t cap)
{
    sel_t *s = &sels[(srcdc >> 2) % NSEL]; dib_t *d; unsigned mn = 255, mx = 0, n = 0; uint64_t sum = 0;
    buf[0] = 0;
    if (s->dc != srcdc || !(d = dib_find(s->bmp)) || d->bpp != 32 || w <= 0 || h <= 0) { snprintf(buf, cap, " srcA=n/a"); return; }
    for (int j = 0; j < 8; j++) for (int i = 0; i < 8; i++) {
        int x = sx + (w - 1) * i / 7, y = sy + (h - 1) * j / 7; uint8_t px[4]; int row;
        if (x < 0 || y < 0 || x >= d->w || y >= d->hh) continue;
        row = d->topdown ? y : d->hh - 1 - y;
        if (!peek(d->bits + ((uint64_t)row * d->w + x) * 4, px, 4)) continue;
        if (px[3] < mn) mn = px[3]; if (px[3] > mx) mx = px[3]; sum += px[3]; n++;
    }
    if (n) snprintf(buf, cap, " srcA[min=%u max=%u mean=%u n=%u]", mn, mx, (unsigned)(sum / n), n);
}

#define NROW 8192
typedef struct { uint32_t id; uint64_t cnt, last; char txt[220]; } row_t;
static row_t rows[NROW]; static unsigned nrows;
static FILE *out; static unsigned dumpno;
#define MAXE 400000
static unsigned ne;
#define MAXDEPTH 64
typedef struct { uint32_t id; uint64_t ra, sp, a[12]; } fr_t;
static fr_t stk[MAXDEPTH]; static int depth;

static FILE *outf(void)
{
    if (!out) { const char *p = getenv("APIW_OUT"); out = fopen(p && *p ? p : "/dev/null", "w"); if (!out) out = stderr; }
    return out;
}

static void decode(const apiw_t *t, char *buf, size_t cap, int post, const fr_t *f)
{
    char s1[96] = "", s2[96] = "";
    uint32_t v = 0;
    const uint64_t *a = f->a;
    buf[0] = 0;
    switch (t->dec) {
    case APIW_D_W1: rd_w(a[0], s1, sizeof s1); snprintf(buf, cap, "\"%s\"", s1); break;
    case APIW_D_A1: rd_a(a[0], s1, sizeof s1); snprintf(buf, cap, "\"%s\"", s1); break;
    case APIW_D_A2: rd_a(a[1], s1, sizeof s1); snprintf(buf, cap, "\"%s\"", s1); break;
    case APIW_D_W2: rd_w(a[1], s1, sizeof s1); snprintf(buf, cap, "\"%s\"", s1); break;
    case APIW_D_W23: rd_w(a[1], s1, sizeof s1); rd_w(a[2], s2, sizeof s2); snprintf(buf, cap, "\"%s\" \"%s\"", s1, s2); break;
    case APIW_D_W3: rd_w(a[2], s1, sizeof s1); snprintf(buf, cap, "flags=%#llx \"%s\"", (unsigned long long)a[1], s1); break;
    case APIW_D_G1G4: rd_g(a[0], s1, sizeof s1); rd_g(a[4], s2, sizeof s2); snprintf(buf, cap, "clsid=%s riid=%s ctx=%#llx", s1, s2, (unsigned long long)a[3]); break;
    case APIW_D_IDX: snprintf(buf, cap, "idx=%u", (unsigned)a[0]); break;
    case APIW_D_DEVCAPS: snprintf(buf, cap, "idx=%u", (unsigned)a[1]); break;
    case APIW_D_SPI: snprintf(buf, cap, "action=%#x uiParam=%llu", (unsigned)a[0], (unsigned long long)a[1]); if (post && peek(a[2], &v, 4)) { size_t l = strlen(buf); snprintf(buf + l, cap - l, " pv32=%u", v); } break;
    case APIW_D_PTR1U32: snprintf(buf, cap, "p"); if (post && peek(a[0], &v, 4)) { size_t l = strlen(buf); snprintf(buf + l, cap - l, " *p=%u", v); } break;
    case APIW_D_CREATEWIN:
        { char cl[96], ti[64];
          rd_w(a[1], cl, sizeof cl); rd_w(a[2], ti, sizeof ti);
          snprintf(buf, cap, "ex=%#x style=%#x class=\"%s\" title=\"%s\" x=%d y=%d w=%d h=%d parent=%#llx", (unsigned)a[0], (unsigned)a[3], cl, ti, (int)a[4], (int)a[5], (int)a[6], (int)a[7], (unsigned long long)a[8]); }
        break;
    case APIW_D_H1: snprintf(buf, cap, "h=%#llx a2=%#llx a3=%#llx a4=%#llx", (unsigned long long)a[0], (unsigned long long)a[1], (unsigned long long)a[2], (unsigned long long)a[3]); break;
    case APIW_D_SWP: snprintf(buf, cap, "h=%#llx after=%#llx x=%d y=%d cx=%d cy=%d flags=%#x", (unsigned long long)a[0], (unsigned long long)a[1], (int)a[2], (int)a[3], (int)a[4], (int)a[5], (unsigned)a[6]); break;
    case APIW_D_SLWA: snprintf(buf, cap, "h=%#llx key=%#x alpha=%u flags=%#x", (unsigned long long)a[0], (unsigned)a[1], (unsigned)(a[2] & 0xff), (unsigned)a[3]); break;
    case APIW_D_ULW: snprintf(buf, cap, "h=%#llx hdcDst=%#llx pptDst=%#llx psize=%#llx hdcSrc=%#llx", (unsigned long long)a[0], (unsigned long long)a[1], (unsigned long long)a[2], (unsigned long long)a[3], (unsigned long long)a[4]); break;
    case APIW_D_BITBLT: snprintf(buf, cap, "dst=%#llx at %d,%d size %dx%d src=%#llx from %d,%d rop=%#x", (unsigned long long)a[0], (int)a[1], (int)a[2], (int)a[3], (int)a[4], (unsigned long long)a[5], (int)a[6], (int)a[7], (unsigned)a[8]); break;
    case APIW_D_STRETCHBLT: snprintf(buf, cap, "dst=%#llx at %d,%d size %dx%d src=%#llx from %d,%d size %dx%d rop=%#x", (unsigned long long)a[0], (int)a[1], (int)a[2], (int)a[3], (int)a[4], (unsigned long long)a[5], (int)a[6], (int)a[7], (int)a[8], (int)a[9], (unsigned)a[10]); break;
    case APIW_D_CREATEDIB: { uint32_t hdr[5] = {0}; peek(a[1], hdr, 20); snprintf(buf, cap, "hdc=%#llx bmi: size=%u %dx%d planes/bpp=%#x usage=%u", (unsigned long long)a[0], hdr[0], (int)hdr[1], (int)hdr[2], hdr[3], (unsigned)a[2]); } break;
    case APIW_D_SELOBJ: snprintf(buf, cap, "dc=%#llx obj=%#llx", (unsigned long long)a[0], (unsigned long long)a[1]); break;
    case APIW_D_MARGINS: { int32_t m[4] = {0}; peek(a[1], m, 16); snprintf(buf, cap, "h=%#llx margins L=%d R=%d T=%d B=%d", (unsigned long long)a[0], m[0], m[1], m[2], m[3]); } break;
    case APIW_D_STK: {   /* a guess at the guest call chain: words of the guest stack that point just behind a call instruction in the engine / QFC / ILTools code */
        uint64_t w[192] = {0}; size_t l; int shown = 0;
        snprintf(buf, cap, "h=%#llx stk=", (unsigned long long)a[0]);
        peek(f->sp, w, sizeof w);
        for (unsigned i = 1; i < 192 && shown < 16; i++) {
            uint64_t v = w[i]; uint8_t b[8];
            if (!((v >= 0x401000 && v < 0x1976000) || (v >= 0x1d00000 && v < 0x1f10000) || (v >= 0x6000000 && v < 0x6394000))) continue;
            if (!peek(v - 8, b, 8)) continue;
            if (b[3] == 0xE8 || (b[2] == 0xFF && (b[3] & 0x38) == 0x10) || (b[1] == 0xFF && (b[2] & 0x38) == 0x10) || (b[4] == 0xFF && (b[5] & 0x38) == 0x10) || (b[5] == 0xFF && (b[6] & 0x38) == 0x10) || (b[6] == 0xFF && (b[7] & 0x38) == 0x10)) { l = strlen(buf); snprintf(buf + l, cap - l, "%#llx ", (unsigned long long)v); shown++; }
        }
        } break;
    default: break;
    }
}

void apiw_pre(unsigned id)
{
    apiw_t *t = &apiw_tab[id];
    t->n++;
    if (!(t->flags & (APIW_F_PROBE | APIW_F_EVENT))) return;
    if (depth >= MAXDEPTH) { depth++; return; }
    fr_t *f = &stk[depth++];
    f->id = id; f->ra = 0; f->sp = R[4];
    peek(R[4], &f->ra, 8);
    f->a[0] = R[1]; f->a[1] = R[2]; f->a[2] = R[8]; f->a[3] = R[9];
    for (unsigned k = 4; k < 12; k++) { uint64_t v = 0; if (!peek(R[4] + 0x28u + 8u * (k - 4u), &v, 8)) v = 0; f->a[k] = v; }
}

void apiw_post(unsigned id)
{
    apiw_t *t = &apiw_tab[id];
    char txt[280], line[480];
    if (!(t->flags & (APIW_F_PROBE | APIW_F_EVENT))) return;
    if (depth > MAXDEPTH) { depth--; return; }
    if (depth <= 0) return;
    fr_t *f = &stk[--depth];
    if (f->id != id) return;
    decode(t, txt, sizeof txt, 1, f);
    if (t->dec == APIW_D_CREATEDIB) { uint64_t bits = 0; uint32_t hdr[4] = {0}; peek(f->a[3], &bits, 8); peek(f->a[1], hdr, 16); if (R[0]) dib_add(R[0], bits, (int)hdr[1], (int)hdr[2], (int)(hdr[3] >> 16)); }
    if (t->dec == APIW_D_SELOBJ) sel_set(f->a[0], f->a[1]);
    if (t->dec == APIW_D_BITBLT && getenv("APIW_SRCALPHA")) { char sa[100]; src_alpha(f->a[5], (int)f->a[6], (int)f->a[7], (int)f->a[3], (int)f->a[4], sa, sizeof sa); size_t l = strlen(txt); snprintf(txt + l, sizeof txt - l, "%s", sa); }
    snprintf(line, sizeof line, "%s ra=%#llx ret=%#llx", txt, (unsigned long long)f->ra, (unsigned long long)R[0]);
    if (t->flags & APIW_F_PROBE) {
        unsigned k;
        for (k = 0; k < nrows; k++) if (rows[k].id == id && !strcmp(rows[k].txt, line)) { rows[k].cnt++; break; }
        if (k == nrows && nrows < NROW) { rows[nrows].id = id; rows[nrows].cnt = 1; rows[nrows].last = 0; snprintf(rows[nrows].txt, sizeof rows[nrows].txt, "%s", line); nrows++; }
    }
    if (t->flags & APIW_F_EVENT) {
        if (ne++ < MAXE) fprintf(outf(), "E %llu %s %s\n", (unsigned long long)(fle_sys_clock_ticks() / 10000u), t->name, line);
    }
}

void apiw_dump(void)
{
    FILE *o = outf();
    fprintf(o, "#dump %u clock_ms %llu\n", ++dumpno, (unsigned long long)(fle_sys_clock_ticks() / 10000u));
    for (unsigned i = 0; i < apiw_n; i++) {
        apiw_t *t = &apiw_tab[i];
        if (t->n != t->last) { fprintf(o, "A %s %llu\n", t->name, (unsigned long long)(t->n - t->last)); t->last = t->n; }
    }
    for (unsigned k = 0; k < nrows; k++) if (rows[k].cnt != rows[k].last) { fprintf(o, "P %s %llu %s\n", apiw_tab[rows[k].id].name, (unsigned long long)(rows[k].cnt - rows[k].last), rows[k].txt); rows[k].last = rows[k].cnt; }
    fflush(o);
}

int __wrap_getrusage(int who, struct rusage *ru)
{
    int r = __real_getrusage(who, ru);
    if (who == RUSAGE_SELF) apiw_dump();
    return r;
}
